            return 0
        s = dist_of(depot, r[0])
        for i in range(len(r) - 1):
            s += dist_of(r[i], r[i + 1])
        return s + dist_of(r[-1], depot)

    def route_load(r):
        s = 0
        for x in r:
            s += demand_of(x)
        return s

    changed = True
    while changed:
        changed = False
        for i in range(len(final_routes)):
            r = final_routes[i]
            if len(r) < 4:
                continue
            improved = True
            while improved:
                improved = False
                n = len(r)
                best_gain = 0
                bi = bj = -1
                for a in range(n - 2):
                    p = depot if a == 0 else r[a - 1]
                    q = r[a]
                    for b in range(a + 2, n):
                        u = r[b]
                        v = depot if b == n - 1 else r[b + 1]
                        gain = (dist_of(p, q) + dist_of(u, v)) - (dist_of(p, u) + dist_of(q, v))
                        if gain > best_gain:
                            best_gain = gain
                            bi, bj = a, b
                if best_gain > 0:
                    r[bi:bj + 1] = reversed(r[bi:bj + 1])
                    improved = True
                    changed = True
            final_routes[i] = r

    return final_routes
